    }
  ],
  "problems": [
    {
      "problem": "Potential customer drop-off on web estimates if visitors do not have an active default email client installed or configured.",
      "label": "inference",
      "basis": "The contact form on https://walkerelectricidaho.com/contact/ indicates 'This opens your email app with the details filled in so you can review before sending', which fails if the browser or operating system lacks a default mail client."
    },
    {
      "problem": "Missed phone calls or delayed email responses during active on-site electrical work.",
      "label": "hypothesis",
      "basis": "For a solo electrician working in the field during business hours (7:00 AM - 5:00 PM), answering calls and manually replying to emails simultaneously may cause delays."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Standard server-side web form handler (e.g., standard website contact form plugin or email relay)",
